// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address fuzzDepositorAccount, address caller) public {
        vm.assume(fuzzDepositorAccount != address(0));
        vm.assume(caller != address(0));

        address other = address(uint160(uint256(keccak256(abi.encodePacked(caller, uint256(1))))));
        vm.assume(other != caller);

        bool okCaller;
        vm.prank(caller);
        try c.setL1BlockValues({
            _number: 1,
            _timestamp: 1,
            _basefee: 1,
            _hash: bytes32(0),
            _sequenceNumber: 1,
            _batcherHash: bytes32(0),
            _l1FeeOverhead: 1,
            _l1FeeScalar: 1
        }) {
            okCaller = true;
        } catch {
            okCaller = false;
        }

        bool okOther;
        vm.prank(other);
        try c.setL1BlockValues({
            _number: 1,
            _timestamp: 1,
            _basefee: 1,
            _hash: bytes32(0),
            _sequenceNumber: 1,
            _batcherHash: bytes32(0),
            _l1FeeOverhead: 1,
            _l1FeeScalar: 1
        }) {
            okOther = true;
        } catch {
            okOther = false;
        }

        address onchainDepositor = c.depositorAccount();

        assertTrue(okCaller == (caller == onchainDepositor) && okOther == (other == onchainDepositor));
    }
}
